html:
{%- set s = get_statement_of_account(doc.name) -%}
{#- Every class is prefixed with "soa-": Frappe's print CSS is Bootstrap based and defines common names such as .label and .info. Its print reset also sets `color: #000` on every element, so text colours are set on the elements that hold the text rather than inherited. -#}
<style>
	.soa {
		font-family: "Times New Roman", "Liberation Serif", "Nimbus Roman", "Noto Serif", Times, serif;
		font-size: 12px;
	}
	.soa table {
		width: 100%;
		border-collapse: collapse;
		table-layout: fixed;
	}
	.soa table th,
	.soa table td {
		border: 1px solid #b8c0c8;
		color: #1f2933;
		padding: 5px 6px !important;
		vertical-align: top;
		word-wrap: break-word;
	}
	.soa table td.soa-banner {
		background-color: #fff;
		border: 0;
		border-bottom: 3px solid #1f3a5f;
		padding: 6px 10px 12px !important;
		text-align: center;
	}
	.soa .soa-title {
		color: #1f3a5f;
		font-size: 24px;
		font-weight: bold;
		letter-spacing: 1px;
	}
	.soa .soa-subtitle {
		color: #52606d;
		font-size: 14px;
		font-weight: bold;
		margin-top: 4px;
	}
	.soa table td.soa-label {
		background-color: #eef1f5;
		font-weight: bold;
	}
	.soa table td.soa-total {
		color: #1f3a5f;
		font-weight: bold;
	}
	.soa .soa-gap {
		height: 10px;
	}
	.soa table.soa-items {
		margin-top: 16px;
	}
	.soa table.soa-items th {
		background-color: #1f3a5f;
		border-color: #1f3a5f;
		color: #fff;
		font-weight: bold;
		text-align: left;
	}
	.soa table.soa-items td {
		padding-top: 9px !important;
		padding-bottom: 9px !important;
	}
	.soa table.soa-items thead {
		display: table-header-group;
	}
	.soa table.soa-items tr {
		page-break-inside: avoid;
	}
	.soa table.soa-items .soa-num {
		text-align: right;
	}
	.soa table.soa-items td.soa-num,
	.soa table.soa-items td.soa-nowrap {
		white-space: nowrap;
	}
	.soa table.soa-items .soa-center {
		text-align: center;
	}
</style>

<div class="soa">
	<table>
		<tr>
			<td class="soa-banner">
				<div class="soa-title">STATEMENT OF ACCOUNT</div>
				<div class="soa-subtitle">(RECEIVABLE)</div>
			</td>
		</tr>
	</table>
	<div class="soa-gap"></div>

	<table>
		<colgroup>
			<col style="width: 14%">
			<col style="width: 36%">
			<col style="width: 14%">
			<col style="width: 36%">
		</colgroup>
		<tr>
			<td class="soa-label">M/S:</td>
			<td>{{ s.customer_name | e }}</td>
			<td class="soa-label">Statement Date</td>
			<td>{{ s.statement_date }}</td>
		</tr>
		<tr>
			<td class="soa-label">Attn:</td>
			<td>{{ s.attn | e }}</td>
			<td class="soa-label">From</td>
			<td>{{ s.company_name | e }}</td>
		</tr>
		<tr>
			<td class="soa-label">Tel:</td>
			<td>{{ s.phone | e }}</td>
			<td class="soa-label">TRN</td>
			<td>{{ s.company_tax_id | e }}</td>
		</tr>
		<tr>
			<td class="soa-label">Client TRN</td>
			<td>{{ s.customer_tax_id | e }}</td>
			<td class="soa-label">Email</td>
			<td>{{ s.company_email | e }}</td>
		</tr>
	</table>

	<table class="soa-items">
		<colgroup>
			<col style="width: 11%">
			<col style="width: 18%">
			<col style="width: 16%">
			<col style="width: 15%">
			<col style="width: 11%">
			<col style="width: 10%">
			<col style="width: 11%">
			<col style="width: 8%">
		</colgroup>
		<thead>
			<tr>
				<th>Date</th>
				<th>Invoice Number</th>
				<th>Description</th>
				<th>Payment Stage</th>
				<th class="soa-num">Amount ({{ s.currency | e }})</th>
				<th class="soa-num">Received</th>
				<th class="soa-num">Balance ({{ s.currency | e }})</th>
				<th class="soa-center">Due Days</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in s.rows %}
			<tr>
				<td class="soa-nowrap">{{ row.date }}</td>
				<td>{{ row.invoice | e }}</td>
				<td>{{ row.description | e }}</td>
				<td>{{ row.payment_stage | e }}</td>
				<td class="soa-num">{{ row.amount }}</td>
				<td class="soa-num">{{ row.received }}</td>
				<td class="soa-num">{{ row.balance }}</td>
				<td class="soa-center">{{ row.due_days }}</td>
			</tr>
			{%- else %}
			<tr>
				<td colspan="8" class="soa-center">No pending invoices</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	<table>
		<colgroup>
			<col style="width: 50%">
			<col style="width: 50%">
		</colgroup>
		<tr>
			<td class="soa-label">Total Amount</td>
			<td>{{ s.total_amount }}</td>
		</tr>
		<tr>
			<td class="soa-label">Total Received</td>
			<td>{{ s.total_received }}</td>
		</tr>
		<tr>
			<td class="soa-label">Outstanding</td>
			<td class="soa-total">{{ s.outstanding }}</td>
		</tr>
	</table>
</div>
